insert into natural_english_private.catalogue(module,senses,questions) values
('advanced-native-550', '["phrase"]'::jsonb, '{"advanced-native-550-v1-audio":{"type":"mc","answers":["What people experience while waiting, not only how fast the queue moves."],"options":["A measured finding that the queue is shorter after the preview was installed.","What people experience while waiting, not only how fast the queue moves.","A claim that entry speed no longer affects anyone.","A plan to remove the display because the children have already seen it."]},"advanced-native-550-v2-reply":{"type":"mc","answers":["It made us consider the waiting experience as well as the entry speed.","We saw the queue from a different angle by asking what children could see while waiting.","It added a question about what happens to visitors before they reach the entrance.","We began considering a preview in the waiting area, not just faster entry."],"options":["It made us consider the waiting experience as well as the entry speed.","We saw the queue from a different angle by asking what children could see while waiting.","It added a question about what happens to visitors before they reach the entrance.","We began considering a preview in the waiting area, not just faster entry."]},"advanced-native-550-v1-scene":{"type":"mc","answers":["She is looking at the task from a different angle by asking who gets a chance to participate."],"options":["She is looking at the task from a different angle by asking who gets a chance to participate.","The exercise has already been changed to include a private writing stage before discussion.","She is only repeating the same question about speed without adding another concern."]},"advanced-native-550-v1-contrast":{"type":"mc","answers":["Repeat the same claim in new wording without changing what is considered."],"options":["Consider an audience’s experience as well as the organiser’s efficiency.","Ask how a plan affects a group whose needs were not considered.","Repeat the same claim in new wording without changing what is considered."]},"advanced-native-550-v1-branch":{"type":"mc","answers":["We can examine both the wait and the entry process, then test which changes help each part."],"options":["We can examine both the wait and the entry process, then test which changes help each part.","Stop measuring entry delays and use the preview as the only response to the queue.","Ask only the staff to assess the waiting experience, without including the people who actually waited."]},"advanced-native-550-v1-final":{"type":"open","answers":["We could show the silence from a different angle by adding the letters the other character has written to the old address. That would reveal different information without dismissing the first character’s hurt.","Looking at the scene from a different angle could let readers see the unanswered letters rather than assume deliberate rejection. I would add a brief passage from the sender’s view while keeping the recipient’s uncertainty."],"options":[]}}'::jsonb),
('advanced-native-551', '["phrase"]'::jsonb, '{"advanced-native-551-v1-audio":{"type":"mc","answers":["Editing felt familiar, and the speaker would try one interview question with support."],"options":["The speaker agreed to join the interview only after it had finished recording.","The speaker rejected all participation, including the editing work.","Editing felt familiar, and the speaker would try one interview question with support.","Interviewing already felt easier than editing, so the speaker would lead the whole programme alone."]},"advanced-native-551-v2-reply":{"type":"mc","answers":["It is outside my comfort zone, so I will begin with one supported question rather than the whole programme.","I have agreed to a small interview role while keeping the host’s guidance.","The first attempt will be prepared and limited in scope, not an entire solo programme.","I will ask one prepared question with the experienced host beside me."],"options":["It is outside my comfort zone, so I will begin with one supported question rather than the whole programme.","I have agreed to a small interview role while keeping the host’s guidance.","The first attempt will be prepared and limited in scope, not an entire solo programme.","I will ask one prepared question with the experienced host beside me."]},"advanced-native-551-v1-scene":{"type":"mc","answers":["Watercolour is beyond her comfort zone, so she is starting with a small colour study."],"options":["The small study means she has accepted a large watercolour commission.","Watercolour is beyond her comfort zone, so she is starting with a small colour study.","She already feels equally at ease with every watercolour commission as with pencil sketches."]},"advanced-native-551-v1-contrast":{"type":"mc","answers":["The person is definitely incapable of learning it."],"options":["The person is definitely incapable of learning it.","Preparation or a supported first step may help the person decide whether to try.","The activity goes beyond what feels familiar and easy to that person."]},"advanced-native-551-v1-branch":{"type":"mc","answers":["Keep the distinction between familiar editing and a new interview role, and describe the supported first step I agreed to."],"options":["Keep me on editing only and postpone the prepared question, although I have agreed to try it with the host.","Keep the distinction between familiar editing and a new interview role, and describe the supported first step I agreed to.","Remove me from both editing and interviewing without discussing the role I am ready to try."]},"advanced-native-551-v1-final":{"type":"open","answers":["Thank you for inviting me, but I want to stay within my comfort zone this weekend and spend a quiet afternoon sketching. After the move, familiar drawing feels like the rest I need, rather than a failure to be adventurous.","I appreciate the invitation, though I am choosing my comfort zone this time because the week has been demanding. I would like some familiar sketching instead of another new activity just now."],"options":[]}}'::jsonb),
('advanced-native-552', '["phrase"]'::jsonb, '{"advanced-native-552-v1-audio":{"type":"mc","answers":["Members could choose a problem to discuss before hearing the notices."],"options":["The chair read all the notices first and left the members’ chosen problem until the end.","The chair chose the opening problem herself and asked members only to listen to her answer.","The opening kept announcements as the only activity, with no member choice.","Members could choose a problem to discuss before hearing the notices."]},"advanced-native-552-v2-reply":{"type":"mc","answers":["The opening made room for a concern members wanted to explore.","I welcomed the chance to discuss something before the usual notices.","She let members choose a problem instead of starting only with announcements.","It was a breath of fresh air because we had a real choice about what to discuss first."],"options":["The opening made room for a concern members wanted to explore.","I welcomed the chance to discuss something before the usual notices.","She let members choose a problem instead of starting only with announcements.","It was a breath of fresh air because we had a real choice about what to discuss first."]},"advanced-native-552-v1-scene":{"type":"mc","answers":["The honest beginner column was a breath of fresh air for her, though we do not know how other readers responded."],"options":["The honest beginner column was a breath of fresh air for her, though we do not know how other readers responded.","A reader survey has already confirmed that this column is the magazine’s most popular feature.","She preferred the older impression that nobody faced difficulty and found the new column unwelcome."]},"advanced-native-552-v1-contrast":{"type":"mc","answers":["A change is new, but the speaker finds it less helpful and does not welcome it."],"options":["A welcome change gives someone new energy or relief.","A change is new, but the speaker finds it less helpful and does not welcome it.","A person brings an approach that someone finds refreshing."]},"advanced-native-552-v1-branch":{"type":"mc","answers":["Say why I welcomed the change, and ask other members before making a claim about everyone."],"options":["Use my positive reaction as the group’s final assessment without asking anyone else.","Keep the next meeting announcement-only and collect reactions to the changed opening afterwards.","Say why I welcomed the change, and ask other members before making a claim about everyone."]},"advanced-native-552-v1-final":{"type":"open","answers":["The lively new piece is a breath of fresh air after so many slow songs, and I am glad you suggested it. Could we keep one familiar slower piece too, so the programme has a contrast?","Your choice feels like a breath of fresh air for our rehearsals because it brings a different rhythm. I would enjoy playing it alongside one of the slower pieces rather than replacing them all."],"options":[]}}'::jsonb),
('advanced-native-553', '["phrase"]'::jsonb, '{"advanced-native-553-v1-audio":{"type":"mc","answers":["She used readers’ questions to improve explanations and still sought help where needed."],"options":["She used readers’ questions to improve explanations and still sought help where needed.","She counted the number of comments without changing any explanation.","She now handles complex interviews without asking for advice.","She avoided comparing comments with the text because feedback was meant only to praise her."]},"advanced-native-553-v2-reply":{"type":"mc","answers":["The comments gave her a way to improve rather than only a score to collect.","It helped her identify explanations readers did not understand.","It became the engine of personal development by guiding clearer revisions to her drafts.","She could connect the questions with changes she made in the text."],"options":["The comments gave her a way to improve rather than only a score to collect.","It helped her identify explanations readers did not understand.","It became the engine of personal development by guiding clearer revisions to her drafts.","She could connect the questions with changes she made in the text."]},"advanced-native-553-v1-scene":{"type":"mc","answers":["Learning to listen before replying became the engine of personal development in his relationships."],"options":["Learning to listen before replying became the engine of personal development in his relationships.","His progress came from replying sooner, leaving less time for the other person to finish.","The feedback concerned his written spelling, rather than how he took turns in conversation."]},"advanced-native-553-v1-contrast":{"type":"mc","answers":["That factor is the only possible cause of all improvement."],"options":["A factor supports continuing individual growth.","That factor is the only possible cause of all improvement.","The context can describe how ability or understanding changes."]},"advanced-native-553-v1-branch":{"type":"mc","answers":["Ask which comments led to changes and what became clearer, rather than count feedback alone."],"options":["Ask which comments led to changes and what became clearer, rather than count feedback alone.","Choose the learner with the largest pile of comments without looking at any revision.","Judge the improvement from how encouraging the comments sound, without comparing the revised explanations."]},"advanced-native-553-v1-final":{"type":"open","answers":["Listening across generations could be the engine of personal development for me if I question my assumptions about family life. I would keep notes on what changes my understanding, rather than treat participation as just another line on a form.","I hope these conversations can become the engine of personal development by helping me see experiences beyond my own. I am ready to record which of my assumptions I need to reconsider."],"options":[]}}'::jsonb),
('advanced-native-554', '["phrase"]'::jsonb, '{"advanced-native-554-v1-audio":{"type":"mc","answers":["New accounts of work led the speaker to ask questions beyond earlier experience."],"options":["The recording confirmed the speaker’s old questions without raising any different ones.","New accounts of work led the speaker to ask questions beyond earlier experience.","The speaker had already worked in the newly described jobs before joining the recording.","The speaker heard only accounts of the same job they already knew well."]},"advanced-native-554-v2-reply":{"type":"mc","answers":["I heard about jobs outside the range I had previously considered.","It widened my horizons by bringing residents’ unfamiliar working experiences into my questions.","I began asking about work I had not known how to imagine before.","Those conversations gave me new subjects to explore rather than complete expertise."],"options":["I heard about jobs outside the range I had previously considered.","It widened my horizons by bringing residents’ unfamiliar working experiences into my questions.","I began asking about work I had not known how to imagine before.","Those conversations gave me new subjects to explore rather than complete expertise."]},"advanced-native-554-v1-scene":{"type":"mc","answers":["The discussion broadened my horizons by introducing a way of ending a story I had not considered."],"options":["The discussion settled which ending the writer must choose for the reader’s own unfinished story.","The reader concluded that the ending clearly settled the disagreement, rather than leaving reconciliation open.","The discussion broadened my horizons by introducing a way of ending a story I had not considered."]},"advanced-native-554-v1-contrast":{"type":"mc","answers":["Someone repeats a familiar activity without encountering or considering anything new."],"options":["Someone repeats a familiar activity without encountering or considering anything new.","Reading accounts of unfamiliar lives changes the questions someone asks.","New experiences lead someone to consider ideas beyond what they knew."]},"advanced-native-554-v1-branch":{"type":"mc","answers":["Say which accounts opened new questions for me, while keeping clear that I am still learning about those jobs."],"options":["Say which accounts opened new questions for me, while keeping clear that I am still learning about those jobs.","Describe the first recording as the final answer to the questions it has just raised.","Keep only the familiar job in the account and omit the new work experiences that changed my questions."]},"advanced-native-554-v1-final":{"type":"open","answers":["I would like to try it because a cooperative game could widen my horizons beyond the competitive games I know. Could you guide us through one round so I can see how the shared decisions work?","This could broaden my horizons by showing me a different way for players to solve a problem together. I would welcome a short demonstration before we begin, rather than assume the rules are the same as my usual games."],"options":[]}}'::jsonb),
('advanced-native-555', '["phrase"]'::jsonb, '{"advanced-native-555-v1-audio":{"type":"mc","answers":["Transport, meals and room use changed, while the Sunday call continued."],"options":["Meals and transport stayed as before; only the Sunday call changed.","The family had already returned to its old home before the bus time changed.","Transport, meals and room use changed, while the Sunday call continued.","Every family routine stopped, including the Sunday call."]},"advanced-native-555-v2-reply":{"type":"mc","answers":["It turned our routine upside down, although we still kept the Sunday call.","Several familiar arrangements changed at once, rather than just one small detail.","The family needed to adapt its timings and room use while keeping one regular contact.","We had earlier transport, later meals and a shared room that also became a study space."],"options":["It turned our routine upside down, although we still kept the Sunday call.","Several familiar arrangements changed at once, rather than just one small detail.","The family needed to adapt its timings and room use while keeping one regular contact.","We had earlier transport, later meals and a shared room that also became a study space."]},"advanced-native-555-v1-scene":{"type":"mc","answers":["The renovation turned the rehearsal arrangements upside down without changing the cast."],"options":["Rehearsals can still use the same room and equipment positions, with only a change to the starting time.","The cast was replaced before anyone discussed the room or equipment.","The renovation turned the rehearsal arrangements upside down without changing the cast."]},"advanced-native-555-v1-contrast":{"type":"mc","answers":["Nothing stable can remain and the change must be permanently harmful."],"options":["Familiar arrangements changed substantially.","Nothing stable can remain and the change must be permanently harmful.","The context can show which parts of life were disrupted."]},"advanced-native-555-v1-branch":{"type":"mc","answers":["Describe the changed timings and room use, but keep the continuing Sunday call in the account."],"options":["Mention only the call and leave out the changes that required the family to adapt.","Describe the changed timings and room use, but keep the continuing Sunday call in the account.","Use the move as a reason to stop the Sunday call without asking anyone whether the time still works."]},"advanced-native-555-v1-final":{"type":"open","answers":["Leading the small group turned his view of himself upside down: he began to imagine teaching as something he could learn. I would keep his need for practice rather than make one session turn him into an expert.","His idea of who he could become was turned upside down by the unexpected teaching role. The ending shows a willingness to practise, not a completely finished transformation."],"options":[]}}'::jsonb),
('advanced-native-556', '["phrase"]'::jsonb, '{"advanced-native-556-v1-audio":{"type":"mc","answers":["The team reviewed the steps and identified a mismatch, while changing the signs remained."],"options":["The signs had already been replaced before anyone read the instructions.","The team only experienced an unpleasant event and did not examine any text.","Both signs were confirmed to use the same entrance name throughout the review.","The team reviewed the steps and identified a mismatch, while changing the signs remained."]},"advanced-native-556-v2-reply":{"type":"mc","answers":["Comparing the instructions with the signs showed where visitors could be confused.","The review identified a change needed in the signs, rather than completing it.","The entrance step used names that did not match across the two signs.","We went through the steps and found a mismatch at the entrance."],"options":["Comparing the instructions with the signs showed where visitors could be confused.","The review identified a change needed in the signs, rather than completing it.","The entrance step used names that did not match across the two signs.","We went through the steps and found a mismatch at the entrance."]},"advanced-native-556-v1-scene":{"type":"mc","answers":["We have gone through the roles and found a welcome task that still needs someone."],"options":["Every role was already assigned before the list was discussed.","The team avoided discussing the role list and only waited for the event to begin.","We have gone through the roles and found a welcome task that still needs someone."]},"advanced-native-556-v1-contrast":{"type":"mc","answers":["Experience a difficult year without discussing or examining a list or process."],"options":["Review the stages of a plan together and raise questions.","Experience a difficult year without discussing or examining a list or process.","Discuss each part of a scene to clarify what happens."]},"advanced-native-556-v1-branch":{"type":"mc","answers":["The review showed what needs changing; let us agree who will make the entrance names consistent."],"options":["Run the same visitor trial again before making any plan to address the known name mismatch.","Archive the review notes and leave the entrance signs as they are for the next event.","The review showed what needs changing; let us agree who will make the entrance names consistent."]},"advanced-native-556-v1-final":{"type":"open","answers":["Could we go through this passage together and stop where the tone changes? I want to try the pauses aloud and hear whether they help the listener follow the feeling.","I would like to go through the letter with you, discussing one change of tone at a time. Could you listen as I try the pauses, rather than give only an overall judgement?"],"options":[]}}'::jsonb),
('advanced-native-558', '["phrase"]'::jsonb, '{"advanced-native-558-v1-audio":{"type":"mc","answers":["The two members handled welcoming and question collection, while text choice remained shared with the tutor."],"options":["Both members continued their original work without any change in responsibility.","The two members handled welcoming and question collection, while text choice remained shared with the tutor.","The two members took over choosing the texts, while the tutor handled only welcoming.","The members were only considering the invitation and had not accepted any duties."]},"advanced-native-558-v2-reply":{"type":"mc","answers":["One welcomed new visitors and the other collected questions.","They took on new roles in welcoming visitors and gathering questions.","They accepted two practical responsibilities without taking over the shared choice of texts.","Their duties expanded to the arrival and question stages of the session."],"options":["One welcomed new visitors and the other collected questions.","They took on new roles in welcoming visitors and gathering questions.","They accepted two practical responsibilities without taking over the shared choice of texts.","Their duties expanded to the arrival and question stages of the session."]},"advanced-native-558-v1-scene":{"type":"mc","answers":["I have been invited to take on a new role, but I am still asking about the time it would require."],"options":["The invitation asks me to redesign the cover rather than contact writers.","I have been invited to take on a new role, but I am still asking about the time it would require.","I have accepted the role and already contacted the contributors."]},"advanced-native-558-v1-contrast":{"type":"mc","answers":["They have received an invitation and are still deciding whether the duties fit."],"options":["They begin the new duty after agreeing its scope with the group.","They have agreed to handle a responsibility that was not theirs before.","They have received an invitation and are still deciding whether the duties fit."]},"advanced-native-558-v1-branch":{"type":"mc","answers":["Keep their agreed duties clear and discuss any further responsibility with them and the group first."],"options":["Remove the new welcoming and question roles because text choice remains shared.","Keep their agreed duties clear and discuss any further responsibility with them and the group first.","Add text selection to their duties now and inform the group after the next session."]},"advanced-native-558-v1-final":{"type":"open","answers":["I took on a new role by leading the five-minute opening before handing the interview back to my tutor. Next time I want to leave a clearer pause after my prepared question.","Taking on a new role meant asking the opening question myself, not managing the whole interview alone. I would like to improve how I give the speaker time to answer before the handover."],"options":[]}}'::jsonb),
('advanced-native-559', '["phrase"]'::jsonb, '{"advanced-native-559-v1-audio":{"type":"mc","answers":["The contact responsibility is clear, while collection is still planned for tomorrow."],"options":["The speaker is reassured because the collection was cancelled without a new plan.","The contact person remains unknown, but the speaker has stopped trying to find out.","The contact responsibility is clear, while collection is still planned for tomorrow.","The display has already been collected and returned to its owner."]},"advanced-native-559-v2-reply":{"type":"mc","answers":["It gives me peace of mind because I do not have to guess who is responsible.","One uncertainty about the handover has been cleared up.","The arrangement has a named contact even though the pickup is tomorrow.","I now know whom to contact about the collection."],"options":["It gives me peace of mind because I do not have to guess who is responsible.","One uncertainty about the handover has been cleared up.","The arrangement has a named contact even though the pickup is tomorrow.","I now know whom to contact about the collection."]},"advanced-native-559-v1-scene":{"type":"mc","answers":["The clear directions give me peace of mind before I travel, although I have not arrived yet."],"options":["The directions confirm that I have already reached the correct room.","The map gives me less information about the entrance than I had before.","The clear directions give me peace of mind before I travel, although I have not arrived yet."]},"advanced-native-559-v1-contrast":{"type":"mc","answers":["Every possible problem has been ruled out objectively."],"options":["Every possible problem has been ruled out objectively.","The context can explain what made the person less worried.","A person feels reassured about a concern."]},"advanced-native-559-v1-branch":{"type":"mc","answers":["Keep the reminder: knowing the contact reassures me, but the collection still needs to happen."],"options":["Remove tomorrow’s reminder and check the collection only if the owner asks later.","Arrange a different collector without telling the named contact, since the plan already feels settled.","Keep the reminder: knowing the contact reassures me, but the collection still needs to happen."]},"advanced-native-559-v1-final":{"type":"open","answers":["Knowing you will read it privately gives me peace of mind, and I appreciate the clear plan for a short response at the weekend. Please ask before quoting any part of the draft elsewhere.","Your agreement not to forward the draft brings me peace of mind while I wait for your comments. I am happy to discuss a quotation if you ask me first."],"options":[]}}'::jsonb),
('advanced-native-560', '["phrase"]'::jsonb, '{"advanced-native-560-v1-audio":{"type":"mc","answers":["The slight paper-shade difference mattered less than the missing page."],"options":["The slight paper-shade difference mattered less than the missing page.","The missing page was already found, so only the paper colour remained.","The two colours made the text unreadable to the whole group.","The partner wanted to ignore the page and compare more shades first."]},"advanced-native-560-v2-reply":{"type":"mc","answers":["The next useful step was to restore the complete text rather than keep comparing shades.","The missing page affects the reading more directly than the slight paper-shade difference.","I was sweating the small stuff over the paper, while a page we needed was missing.","The text was readable on both papers, but the group still needed the absent page."],"options":["The next useful step was to restore the complete text rather than keep comparing shades.","The missing page affects the reading more directly than the slight paper-shade difference.","I was sweating the small stuff over the paper, while a page we needed was missing.","The text was readable on both papers, but the group still needed the absent page."]},"advanced-native-560-v1-scene":{"type":"mc","answers":["Correcting the name is not just sweating the small stuff; it affects whether the guest can find the booking."],"options":["The spelling can wait until after entry because the guest’s name is unrelated to finding the booking.","The guest has already found the correct booking and asked us to leave the name unchanged.","Correcting the name is not just sweating the small stuff; it affects whether the guest can find the booking."]},"advanced-native-560-v1-contrast":{"type":"mc","answers":["Ignore a detail even when it creates a clear barrier to participation."],"options":["Check whether a supposedly small issue has a practical consequence.","Do not let minor issues take excessive attention away from the main purpose.","Ignore a detail even when it creates a clear barrier to participation."]},"advanced-native-560-v1-branch":{"type":"mc","answers":["Let the paper shade go, but replace the missing page so the reading has its complete text."],"options":["Remove the last passage from the plan without checking whether the group still wants to read it.","Let the paper shade go, but replace the missing page so the reading has its complete text.","Keep comparing paper shades and leave the absent passage for readers to infer."]},"advanced-native-560-v1-final":{"type":"open","answers":["I should not sweat the small stuff about equal line lengths in the covering note when the poem and address are already checked. I will send it tonight and accept that the editor’s response is still uncertain.","Instead of sweating the small stuff over the note’s spacing, I can use the checked submission details and send the poem before the deadline. A neat message does not need perfectly matching lines."],"options":[]}}'::jsonb),
('advanced-native-561', '["phrase"]'::jsonb, '{"advanced-native-561-v1-audio":{"type":"mc","answers":["Understanding the visitor’s experience led her to ask about wanted help rather than repeat a script."],"options":["She changed the welcome sign but kept her understanding and questions exactly the same.","She decided to ask colleagues to choose help for visitors, rather than ask the visitors themselves.","The discussion concerned only the physical arrangement of the welcome desk.","Understanding the visitor’s experience led her to ask about wanted help rather than repeat a script."]},"advanced-native-561-v2-reply":{"type":"mc","answers":["Her new questions followed a change in how she saw the visitor’s experience.","She moved from repeating a script to responding to the person’s preferences.","She understood the exclusion concern and began asking what help the visitor wanted.","It changed her approach from the inside out, connecting understanding with a different welcome."],"options":["Her new questions followed a change in how she saw the visitor’s experience.","She moved from repeating a script to responding to the person’s preferences.","She understood the exclusion concern and began asking what help the visitor wanted.","It changed her approach from the inside out, connecting understanding with a different welcome."]},"advanced-native-561-v1-scene":{"type":"mc","answers":["His attitude is changing from the inside out, as a new view of cooperation leads him to ask for help."],"options":["He is describing detailed knowledge of the project, rather than a changed attitude towards asking for help.","His attitude is changing from the inside out, as a new view of cooperation leads him to ask for help.","He has only changed his clothes, without rethinking help or acting differently."]},"advanced-native-561-v1-contrast":{"type":"mc","answers":["Only the outward display changes, with no described inner shift."],"options":["A change in understanding affects how someone responds.","Only the outward display changes, with no described inner shift.","A person rethinks a belief and starts acting on the new view."]},"advanced-native-561-v1-branch":{"type":"mc","answers":["Describe the sign change accurately, and look for evidence of changed understanding or responses before claiming an inner shift."],"options":["Use the new sign alone as evidence that her view of visitors has changed.","Replace the questions about visitors’ experience with another redesign of the desk.","Describe the sign change accurately, and look for evidence of changed understanding or responses before claiming an inner shift."]},"advanced-native-561-v1-final":{"type":"open","answers":["Your performance changed from the inside out when you understood the character’s fear of losing a friend. The pauses and averted gaze now seem connected to what the character wants, not just a quieter voice.","Working from the inside out helped you find a reason for the pause before the truth is spoken. I would keep exploring that fear rather than treat lower volume as the whole change."],"options":[]}}'::jsonb),
('advanced-native-562', '["phrase"]'::jsonb, '{"advanced-native-562-v1-audio":{"type":"mc","answers":["She enjoys helping assistants learn, not necessarily holding a formal teaching post."],"options":["She avoids explaining and gives assistants only finished answers.","She completed a formal teaching qualification before beginning to manage the shop.","She enjoys helping assistants learn, not necessarily holding a formal teaching post.","She has left the shop and now works only in a school."]},"advanced-native-562-v2-reply":{"type":"mc","answers":["She is a teacher at heart because helping others learn is what she enjoys most.","Guiding someone through a problem matters more to her than just supplying an answer.","Her favourite part of managing the shop is helping assistants understand what they are doing.","She most enjoys showing new assistants how to solve a problem."],"options":["She is a teacher at heart because helping others learn is what she enjoys most.","Guiding someone through a problem matters more to her than just supplying an answer.","Her favourite part of managing the shop is helping assistants understand what they are doing.","She most enjoys showing new assistants how to solve a problem."]},"advanced-native-562-v1-scene":{"type":"mc","answers":["He describes himself as an artist at heart, while his current job remains accounting."],"options":["He describes himself as an artist at heart, while his current job remains accounting.","The description means he now earns his income mainly from selling paintings.","He has stopped drawing because accounting is his current job."]},"advanced-native-562-v1-contrast":{"type":"mc","answers":["The person necessarily earns their living as a professional artist."],"options":["The person necessarily earns their living as a professional artist.","The statement may be a self-description rather than a formal job title.","The person has a deep interest or inclination towards art."]},"advanced-native-562-v1-branch":{"type":"mc","answers":["Keep her shop role and quote what she values about teaching assistants, rather than invent a different job."],"options":["List schoolteacher as her current job without asking about any actual post.","Remove her interest in teaching from the profile because it is not her job title.","Keep her shop role and quote what she values about teaching assistants, rather than invent a different job."]},"advanced-native-562-v1-final":{"type":"open","answers":["He is curious at heart, asking residents about daily life whenever he visits somewhere unfamiliar. He is happy to admit what he does not know and gives people time to explain their experience.","At heart, he wants to understand how other people live rather than arrive with ready-made answers. On his visits, he listens to residents’ accounts and asks what he has not yet understood."],"options":[]}}'::jsonb),
('advanced-native-563', '["phrase"]'::jsonb, '{"advanced-native-563-v1-audio":{"type":"mc","answers":["Sound editing was new, so the speaker wanted a demonstration before a practice attempt."],"options":["The only unfamiliar part was choosing which photograph to keep, not editing sound.","Sound editing was new, so the speaker wanted a demonstration before a practice attempt.","The speaker had never organised photographs and refused any practice.","The sound edit had already been completed independently before the request."]},"advanced-native-563-v2-reply":{"type":"mc","answers":["I know the photograph work, but I have not learned the sound-editing part yet.","Sound editing is unfamiliar territory for me, so a short demonstration would help me begin.","I want to understand a new part before trying it on a practice copy.","Watching one edit would give me a starting point for the part I do not yet know."],"options":["I know the photograph work, but I have not learned the sound-editing part yet.","Sound editing is unfamiliar territory for me, so a short demonstration would help me begin.","I want to understand a new part before trying it on a practice copy.","Watching one edit would give me a starting point for the part I do not yet know."]},"advanced-native-563-v1-scene":{"type":"mc","answers":["Building a fictional world is unfamiliar territory for me, even though I know how to research a city story."],"options":["The new task is to collect more city records, not to decide how an invented world works.","Building a fictional world is unfamiliar territory for me, even though I know how to research a city story.","I can use the city’s historical records to verify which invented rule governs this imaginary planet."]},"advanced-native-563-v1-contrast":{"type":"mc","answers":["They are permanently incapable of learning about it."],"options":["They may have relevant skills from another area.","Someone lacks familiarity with a particular area.","They are permanently incapable